use super::{editor, net, process, project_rows, sandbox, secrets, service, settings, update};
use crate::Refusal;

/// Generated by capgen: the calls a plugin can make, one method per capability.
/// Only the kernel's bus gateway implements it; each plugin gets a host bound to
/// its own id, so a plugin never names itself or reaches a provider.
pub trait Host {
    /// Calls editor.spawn (editor.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn editor_spawn(&self, launch: editor::EditorLaunch) -> Result<u32, Refusal>;

    /// Calls net.request (net.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn net_request(&self, request: net::Request) -> Result<net::Reply, Refusal>;

    /// Calls process.install (process.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn process_install(
        &self,
        recipe: process::InstallRecipe,
    ) -> Result<process::InstallResult, Refusal>;

    /// Calls project_rows.page (project_rows.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn project_rows_page(
        &self,
        after: core::option::Option<alloc::string::String>,
        limit: u16,
    ) -> Result<project_rows::RowsPage, Refusal>;

    /// Calls sandbox.save_settings (sandbox.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn sandbox_save_settings(
        &self,
        settings: sandbox::SandboxSettings,
        version: u64,
    ) -> Result<(), Refusal>;

    /// Calls sandbox.settings (sandbox.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn sandbox_settings(&self) -> Result<sandbox::StoredSandboxSettings, Refusal>;

    /// Calls secrets.put_from_owner (secrets.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_put_from_owner(
        &self,
        name: alloc::string::String,
    ) -> Result<secrets::Secret, Refusal>;

    /// Calls secrets.find (secrets.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_find(
        &self,
        name: alloc::string::String,
    ) -> Result<core::option::Option<secrets::Secret>, Refusal>;

    /// Calls secrets.forget (secrets.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_forget(&self, secret: secrets::Secret) -> Result<(), Refusal>;

    /// Calls service.status (service.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn service_status(&self) -> Result<service::ServiceState, Refusal>;

    /// Calls service.repair (service.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn service_repair(&self) -> Result<(), Refusal>;

    /// Calls service.install (service.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn service_install(&self) -> Result<(), Refusal>;

    /// Calls service.uninstall (service.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn service_uninstall(&self) -> Result<(), Refusal>;

    /// Calls settings.save_quit (settings.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn settings_save_quit(&self, settings: settings::QuitSettings) -> Result<(), Refusal>;

    /// Calls update.set_channel (update.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn update_set_channel(&self, channel: update::UpdateChannel) -> Result<(), Refusal>;
}
